def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_op = history[-1]
    if last_op == 'C':
        return 'C'

    total_d = 0
    last_d = -1
    for i in range(n):
        if history[i][1] == 'D':
            total_d += 1
        if history[i][0] == 'D':
            last_d = i

    total_c = n - total_d

    run_op_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run_op_d += 1
        else:
            break

    recent_start = n - 12
    if recent_start < 0:
        recent_start = 0
    recent_len = n - recent_start

    recent_c = 0
    for i in range(recent_start, n):
        if history[i][1] == 'C':
            recent_c += 1

    if (total_c * 4 <= n or
        (recent_len >= 8 and recent_c * 4 <= recent_len) or
        (run_op_d >= 3 and total_d * 2 >= n) or
        run_op_d >= 4):
        return 'D'

    if last_my == 'D':
        return 'C'

    if last_d >= 0:
        coop_since_last_d = False
        for j in range(last_d + 1, n):
            if history[j][1] == 'C':
                coop_since_last_d = True
                break
        if not coop_since_last_d:
            if run_op_d >= 3 and total_d * 2 >= n:
                return 'D'
            return 'C'

    return 'D'
